head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil35600";
scwin.list = null;
scwin.calendar = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_nowVars
 * @description 현재 시각 파생값 충전 — as-is JSP 계산분(서버 데이터 아님)
 * @returns {void}
 * @hidden N
 */
scwin.init_nowVars = function () {
    const pc = $c.util.getComponent('dma_pageContext');
    if (!pc || !pc.set || !pc.get) { return; }
    if (!pc.get("today")) { pc.set("today", $c.date.getServerDateTime("yyyyMMdd")); }
};

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — thisMonth
// TODO Stage2: 세션 키 실환경 확인(회신 11항 · user-info 계약에 없는 키) — session.user.corpUsrTpCd

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_corpUsrTpCd", fn: function(){ return ($c.session.getUserInfo("corpUsrTpCd") === '21'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        $;
        if (param.displayDiv === 'calendar') { if (typeof scwin.calendar === 'function') { scwin.calendar(); } else { /* TODO Stage2: [sdd] 문장 자리 EL 삼항 — 미정의 진입 함수 */ } } else { if (typeof scwin.list === 'function') { scwin.list(); } else { /* TODO Stage2: [sdd] 문장 자리 EL 삼항 — 미정의 진입 함수 */ } }
        $("#monthListArea").find("li:first").find("a").addClass("bdl-none");

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil35600.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_listForm = { action: "", method: 'post', target: '' };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.list = list;
        scwin.calendar = calendar;
        scwin.init_nowVars();
        scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil35600.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name listTab_onclick
 * @description 「목록」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listTab_onclick = async function(e){
    try {
        await list()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil35600.listTab_onclick' }); }
};

/**
 * @method
 * @name calTab_onclick
 * @description 「달력」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.calTab_onclick = async function(e){
    try {
        await calendar()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil35600.calTab_onclick' }); }
};

/**
 * @method
 * @name slc_year01_onchange
 * @description slc_year01 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.slc_year01_onchange = async function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        await scwin.schedules1(selfVar.value)

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil35600.slc_year01_onchange' }); }
};

/**
 * @method
 * @name btn_Schedules2_onclick
 * @description 「${month.name}월」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Schedules2_onclick = async function(e){
    try {
        await scwin.schedules2('' + dma_month.get("code") + '')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil35600.btn_Schedules2_onclick' }); }
};

/**
 * @method
 * @name btn_ToExcel_onclick
 * @description btn_ToExcel 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_ToExcel_onclick = async function(e){
    try {
        await scwin.toExcel()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil35600.btn_ToExcel_onclick' }); }
};

/**
 * @method
 * @name btn_monthlyNoti_onclick
 * @description btn_monthlyNoti 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_monthlyNoti_onclick = function(e){
    try {
        scwin.monthlyNoti((String(((dma_pageContext.get("thisMonth") ?? "")) == null ? '' : ((dma_pageContext.get("thisMonth") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("thisMonth") ?? "")) == null ? '' : ((dma_pageContext.get("thisMonth") ?? ""))))); return false

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil35600.btn_monthlyNoti_onclick' }); }
};

/**
 * @method
 * @name btn_AddSchedule_onclick
 * @description btn_AddSchedule 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_AddSchedule_onclick = function(e){
    try {
        scwin.addSchedule()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil35600.btn_AddSchedule_onclick' }); }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description btn_Close 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_Close_onclick = function(e){
    try {
        scwin.close()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil35600.btn_Close_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_ToExcel
 * @description To Excel 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_ToExcel = async function () {
    const sbmOptions = {
        id: "tx_fn_ToExcel",
        method: "post",
        action: "/helper/schedule.do",
        ref: "dma_ToExcelReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_findSchedules_xhr
 * @description find Schedules xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_findSchedules_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_findSchedules_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_findSchedules_xhr", unresolved: "action:self_submit:tx_fn_findSchedules_xhr" };
};

///////// 5. 일반/업무 함수 영역 /////////
async function list() {
    $("#listTab").removeClass().addClass("on");
    $("#calTab").removeClass();
    $c.util.getComponent("dma_ToExcelReq").set("displayDiv", "list");
    await scwin.findSchedules();
}

async function calendar() {
    $("#calTab").removeClass().addClass("on");
    $("#listTab").removeClass();
    $c.util.getComponent("dma_ToExcelReq").set("displayDiv", "calendar");
    await scwin.findSchedules();
}

/**
 * @method
 * @name monthlyNoti
 * @description monthly Noti 처리
 * @param {*} thisMonth thisMonth
 * @returns {void}
 * @hidden N
 */
scwin.monthlyNoti = function (thisMonth) {
    const _url = "/jldfil35605/jldfil35605.xml?month=" + thisMonth;
    /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
};

/**
 * @method
 * @name schedules1
 * @description schedules1 처리
 * @param {*} year year
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.schedules1 = async function (year) {
    await scwin.findSchedules();
};

/**
 * @method
 * @name schedules2
 * @description schedules2 처리
 * @param {*} month month
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.schedules2 = async function (month) {
    $("#monthListArea").children("li").each(function(i) {
            $(this).find("a").removeClass();
            if ((i + 1) === Number(month)) {
                $(this).find("a").addClass("on");
            }
    });
    $c.util.getComponent("dma_ToExcelReq").set("month", month);
    await scwin.findSchedules();
};

/**
 * @method
 * @name findSchedules
 * @description find Schedules 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.findSchedules = async function () {
    scwin.form_listForm.action = "/helper/schedule.do";
    $c.util.getComponent("dma_ToExcelReq").set("method", "findDisclosureSchedules");
    $c.util.getComponent('txt_scheduleDiv').setValue(await scwin.tx_fn_findSchedules_xhr());
};

/**
 * @method
 * @name addSchedule
 * @description add Schedule 처리
 * @returns {void}
 * @hidden N
 */
scwin.addSchedule = function () {
    const _url = "/helper/updateSchedule.do?method=prepareUpdateDisclosureSchedule";
    /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
};

/**
 * @method
 * @name findSchedule
 * @description find Schedule 처리
 * @param {String} calndDd calndDd
 * @param {*} byddSeq byddSeq
 * @returns {void}
 * @hidden N
 */
scwin.findSchedule = function (calndDd, byddSeq) {
    const _url = "/helper/schedule.do?method=findDisclosureSchedule&calndDd=" + calndDd + "&byddSeq=" + byddSeq;
    /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
};

/**
 * @method
 * @name viewSchedule
 * @description view Schedule 처리
 * @param {*} acptNo acptNo
 * @param {String} schdlAdmItmTpCd schdlAdmItmTpCd
 * @param {*} byddSeq byddSeq
 * @returns {void}
 * @hidden N
 */
scwin.viewSchedule = function (acptNo, schdlAdmItmTpCd, byddSeq) {
    const _url = "/helper/schedule.do?method=occsnDisclsScheduleView&acptNo=" + acptNo + "&schdlAdmItmTpCd=" + schdlAdmItmTpCd + "&byddSeq=" + byddSeq;
    /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
};

/**
 * @method
 * @name close
 * @description close 처리
 * @returns {void}
 * @hidden N
 */
scwin.close = function () {
    $c.win.closePopup();
};

/**
 * @method
 * @name toExcel
 * @description to Excel 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.toExcel = async function () {
    scwin.form_listForm.action = "/helper/schedule.do";
    $c.util.getComponent("dma_ToExcelReq").set("method", "schedulesExcel");
    await scwin.tx_fn_ToExcel();
};
